def knapsack(weights, values, W):
    n = len(weights)
    memo = {}
    def solve(i, cap):
        if i == n or cap == 0:
            return 0
        key = (i, cap)
        if key in memo:
            return memo[key]
        skip = solve(i + 1, cap)
        take = 0
        if weights[i] <= cap:
            take = values[i] + solve(i + 1, cap - weights[i])
        memo[key] = max(skip, take)
        return memo[key]
    return solve(0, W)
